pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Harmonic Best-Fit with Lookahead Pressure (HBF-LP)
    // Minimizes post_residual while penalizing "fragmentation traps" 
    // where the remaining space is too small for common items or the next item.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead zones" (residuals smaller than typical items)
    // Small residuals (1-9) are highly undesirable unless they reach exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0; 
    }

    // 2. Harmonic scaling: Favor residuals that are multiples of larger chunks
    // This aligns with Harmonic Bin Packing logic to pack items of similar size together.
    score += (post_residual % 20) as f64 * 0.5;

    // 3. Lookahead pressure: If the next item cannot fit in this post_residual, 
    // penalize the bin unless it's a perfect fit.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 30.0;
    }

    // 4. Fitting constraints: If this is the only bin that can fit the item,
    // strongly incentivize placing it here to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 5. New bin logic: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only open a new bin if the current "best" fit is poor (high score).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is 35.0. 
        // We only return this if existing bins are unattractive.
        score = 35.0;
    }

    // 6. Global pressure: As we near the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit logic)
    let mut score = post;

    // Penalty for creating small, unusable gaps (1..10)
    // We penalize post_residual values that are likely to be "dead space"
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item fits into the post_residual, reward this bin
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive 
    // about filling bins tightly to avoid fragmentation in later stages.
    let tightness_factor = 15.0 * (1.0 - progress);
    score += (mean_residual - post) * tightness_factor;

    // If this is the ONLY bin that can fit the item, we are forced to take it.
    // However, if we are considering a new bin (bin_residual == bin_capacity),
    // apply a non-linear tax to prevent premature bin opening early in the stream.
    if bin_residual == bin_capacity {
        // New bin penalty: increases as we have more open bins, 
        // but decreases as we reach the end of the stream (to clear remaining items).
        let new_bin_tax = 45.0 * (1.0 - progress) + (open_bins_count as f64 * 2.5);
        score += new_bin_tax;
    } else {
        // Reward bins that have residuals closer to the mean to keep distribution uniform
        score += (post - mean_residual).abs() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tighter packing (lower post_residual)
    let mut score = post * post;

    // Penalty for opening a new bin: only do it if the fit is exceptionally bad
    if bin_residual == bin_capacity {
        // As the stream progresses, become increasingly conservative about opening new bins
        score += 2500.0 * (1.0 + progress.powi(2));
    }

    // Lookahead logic: if the next item is large, prefer bins that leave enough space for it
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap < 0.0 {
            // Penalize bins that would make the next item impossible to fit
            score += 500.0 * gap.abs();
        } else {
            // Reward bins that create a "perfect fit" for the next item
            score -= 100.0 * (1.0 / (1.0 + gap));
        }
    }

    // Heuristic coupling: discourage creating "orphan" residuals that are too small to use (under 10)
    // but incentivize keeping the mean_residual of open bins balanced.
    if post > 0.0 && post < 10.0 {
        score += 200.0 * (1.0 - post / 10.0);
    }

    // Penalty for fragmentation: if many bins are open, favor bins that reduce the mean residual
    if open_bins_count > 0 {
        score += (post - mean_residual).powi(2) * 0.5;
    }

    // If this is the last chance for the current item, lower the penalty significantly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Reward tight packing: If post_residual is small, it's a good fit.
    // However, if post_residual is between 1 and 9, it's often "dead space" 
    // that cannot fit any further items. Penalize this.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2. Lookahead logic: If the next item fits perfectly into the current post_residual,
    // strongly prefer this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward the bin that leaves the smallest gap for the next item
        score -= (100.0 - diff) * 0.5;
    }

    // 3. Prevent fragmentation: If we have many open bins, prioritize filling 
    // the ones that are already emptier (closer to the mean residual) to keep 
    // bins balanced, unless this bin is almost full.
    if open_bins_count > 1 {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 4. Threshold for opening a new bin:
    // If we are forced to open a new bin (bin_residual == bin_capacity), 
    // apply a penalty proportional to the current progress.
    // Early in the stream, we are more conservative.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 25.0 + (progress * 20.0);
    }

    // 5. If this is the last chance for the current item (fitting_bins_count == 1),
    // and it's not a new bin, prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize post_residual if it leaves a "sliver" 
    // (space too small for the smallest possible item, or likely next items).
    // Slivers between 1 and 9 are extremely hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // 2. Lookahead optimization: If next_item_size exists, penalize post_residual 
    // if it's too small to accommodate the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // 3. Open bins pressure: Discourage opening new bins (bin_residual == bin_capacity)
    // unless the fit is perfect or the current open bins are already very full.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many bins already or 
        // if the current mean_residual suggests we have plenty of room elsewhere.
        score += (open_bins_count as f64 * 5.0) + (mean_residual * 0.5);
    } else {
        // Favor bins that become "tight" (low residual) to maximize packing density.
        // We reward bins that result in a post_residual close to 0.
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // 4. Scarcity: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Prioritize Best-Fit (minimize post_residual)
    // 2. Penalize opening a new bin unless the current mean_residual is very high (already cluttered)
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            return 0.0;
        }
        // Penalize new bin creation based on how much space we have left in existing bins
        score = mean_residual * 2.5;
        // If we have few bins open, opening a new one is less catastrophic
        score -= (open_bins_count as f64) * 0.5;
    } else {
        // 3. Lookahead: Reward placements that leave exactly enough room for the next item
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 40.0;
            } else if post_residual > next_item_size {
                // Reward leaving a "buffer" for future items, but penalize excessive wasted space
                score += (post_residual - next_item_size) as f64 * 0.5;
            } else {
                // Severe penalty if we block the next item from fitting
                score += 60.0;
            }
        }

        // 4. Tightness bias: If this is the only bin that fits, we must take it (lower score)
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // 5. Progression scaling: As we approach the end of the stream, be more aggressive with packing
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize large post_residuals (wasted space)
    // We favor bins that leave very little space (tight packing)
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Lookahead: If next_item_size is known, prioritize bins that can accommodate it
    // If next_item_size fits in the post_residual, reduce the score significantly
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Harmonic Class Thresholding:
    // If the post_residual is small but not zero, it's often "dead space" that cannot fit 
    // common item sizes. We penalize residuals in the (0, 10) range heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Global State Awareness:
    // If we are nearing the end of the stream, prioritize closing bins (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual * 0.5);

    // 5. New Bin Policy:
    // If this is a new bin (bin_residual == bin_capacity), set a high baseline cost.
    // Only choose a new bin if the best_fit_penalty (above) is higher than this threshold.
    if bin_residual == bin_capacity {
        score = 65.0 - (progress * 10.0);
    }

    // 6. Scarcity Constraint:
    // If this is the only bin that fits the item (fitting_bins_count == 1), 
    // drastically reduce the score to force the selection of this bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing
    // We target a residual of 0, 1, or 2 as the "harmonic sweet spot"
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // 2. Lookahead Synergy (Modulo Harmonic Coupling)
    // If the next item can fit in the current post_residual, prioritize this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0;
        // Bonus for "perfect" alignment of next item
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 15.0;
        }
    }

    // 3. Fragmentation Avoidance (The "Last Chance" Logic)
    // If this is the only bin that can fit the current item, prioritize it strongly
    // unless the post_residual is extremely wasteful (> 70)
    if fitting_bins_count == 1 && post_residual < 70 {
        score -= 100.0;
    }

    // 4. New Bin Thresholding (Adaptive)
    // Discourage opening a new bin unless the existing bins have poor average residuals
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the mean residual of current bins is high (i.e., they are already crowded)
            score += (mean_residual * 2.0) + (open_bins_count as f64 * 5.0);
        }
    }

    // 5. Harmonic Class Penalty
    // Punish residuals that fall into "dead zones" (e.g., 11-19 space left, hard to fill with common items)
    if post_residual > 10 && post_residual < 20 {
        score += 25.0;
    }

    score
}

